// Repair the slips a model makes in long JSON: a stray or wrong closing
// bracket, a trailing comma, or missing closers at the end (cut-off output).
// Scans outside strings with a bracket stack; drops closers that do not
// match, removes trailing commas, appends missing closers.
function repairJson(str) {
  let out = '';
  const stack = [];
  let inStr = false, esc = false;
  for (const ch of str) {
    if (inStr) {
      out += ch;
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') { inStr = true; out += ch; continue; }
    if (ch === '{' || ch === '[') { stack.push(ch); out += ch; continue; }
    if (ch === '}' || ch === ']') {
      const want = ch === '}' ? '{' : '[';
      if (stack.length && stack[stack.length - 1] === want) {
        stack.pop();
        out = out.replace(/,\s*$/, '');
        out += ch;
      }
      // else: stray closer, drop it
      continue;
    }
    out += ch;
  }
  if (inStr) out += '"';
  out = out.replace(/,\s*$/, '');
  while (stack.length) out += stack.pop() === '{' ? '}' : ']';
  return out;
}

// Split a top-level JSON array into its object texts by bracket depth,
// so one broken object does not take the whole batch down with it.
function topLevelObjects(str) {
  const objs = [];
  let depth = 0, start = -1, inStr = false, esc = false;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{') { if (depth === 0) start = i; depth++; }
    else if (ch === '}') { depth--; if (depth === 0 && start >= 0) { objs.push(str.slice(start, i + 1)); start = -1; } }
  }
  return objs;
}

function normalize(data) {
  if (!data) return [];

  if (Array.isArray(data)) return data;
  if (typeof data === "object") return [data];

  if (typeof data === "string") {
    const cleaned = cleanText(data);

    const whole = safeParse(cleaned) || safeParse(repairJson(cleaned));
    if (Array.isArray(whole)) return whole;
    if (whole && typeof whole === "object") return [whole];

    // Last resort: parse object by object, repairing each.
    const parsed = topLevelObjects(repairJson(cleaned))
      .map(m => safeParse(m) || safeParse(repairJson(m)))
      .filter(Boolean);
    if (parsed.length > 0) return parsed;
  }

  return [];
}

function enforceMinimums(obj) {
  const rules = {
    technical_skills: 3,
    soft_skills: 3,
    core_values: 3,
    motivational_factors: 3,
    typical_tasks: 4,
  };

  for (const [field, minCount] of Object.entries(rules)) {
    if (!Array.isArray(obj[field])) obj[field] = [];
    while (obj[field].length < minCount) {
      obj[field].push("N/A");
    }
  }

  return obj;
}

function sanitize(obj) {
  if (Array.isArray(obj)) {
    return obj.map(sanitize);
  } else if (obj !== null && typeof obj === "object") {
    const clean = {};
    for (const [k, v] of Object.entries(obj)) {
      clean[k] = v === undefined ? null : sanitize(v);
    }
    return clean;
  }
  return obj;
}


